using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking Change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must opt back in.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking Change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so preserve the old id factory.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking Change 3: EF 9 removed support for HasIndex on Cosmos.
            // Cosmos doesn't support secondary indexes via EF; remove HasIndex call.
            // (Index removed — use Cosmos indexing policy directly if needed.)
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Breaking Change 4: EF 9 enables sync I/O blocking by default.
    // SyncJob.cs uses synchronous ToList()/SaveChanges() — these now throw by default.
    // Fix: either switch to async (ToListAsync/SaveChangesAsync) or configure the context
    // (shown in OnConfiguring below).
}

